contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        require(address(this).balance >= _am);
        require(_am > 0);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: _am}(); if (__ESBMC_reverted()) return;

        uint balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;

        assert(!reverted && address(c).balance >= _am - (balanceBefore - balanceAfter) ? balanceAfter <= balanceBefore : true);
    }

    receive() external payable {}
}

