    }

    function _run(uint256 _am) internal {
        _am = bound(_am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _am);
        vm.assume(_am > 0);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: _am}() {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
